def __get_drive_treeitem(tree_item:dict, drive:str) -> dict:
    """
    Use the function to update the tree item to point to the given drive

    :params: tree_item, dict: the tree item to update
          drive, str: the given drive, for example C:, or D:, etc.
    :return: the updated tree item that has the drive assigned to the given drive.
    """
    tree_item["text"] = objectmaphelper.Wildcard(f"*({drive})")
    return tree_item

def __get_child_treeitem(parent_folder_TreeItem:dict, folder:str) -> dict:
    """
    Use tot get the child tree item of the parent folder tree item with given folder.

    :params: dict parent_folder_TreeItem: the given parent folder tree item
             str folder: the foler name of the given child tree item
    :return: the updated child folder tree item
    """
    child_folder_TreeItem = {"container": parent_folder_TreeItem, "text": "", "type": "TreeItem"}
    child_folder_TreeItem["text"] = folder
    return child_folder_TreeItem

def __get_treeitems(drive_tree_item:dict, full_path:str) -> list:
    """
    Use tot get the all the child tree items of a tree item the give full path.

    :params: dict drive_tree_item: the drive tree item place holder
             str full_path: the given full path
    :return: list:  all the child folder tree items
    """
    folder_tree_items = []
    #drive_folder = os.path.splitdrive(full_path)
    paths = full_path.split("\\")
    for i in range(0, len(paths)):
        folder_tree_item = __get_child_treeitem(folder_tree_item, paths[i]) if i > 0 else __get_drive_treeitem(drive_tree_item, paths[i])
        folder_tree_items.append(folder_tree_item)
    return folder_tree_items

@deco.set_separate_app_context(MONACO_APP_NAME)
def await_dicom_import_dialog(waitTimeout:int=20000) -> bool:
    """
    Wait for Dicom Import dialog

    :param: waitTimeout (int), milliseconds of wait timeout.
    :return: a bool, True or False, to indicate if the dialog exists or not.
    """
    return True if CommonActions.wait_for_object_exists(MonacoDicomImportObjects.dICOM_Import_Dialog,waitTimeout) is not None else False

@deco.set_separate_app_context(MONACO_APP_NAME)
def browse_folder(drive:str="C:", root_folder:str="JDICOM", patient_folder:str="PatientLiver"):
    """
    Use to browse the immediate folder of a given drive, e.g. C:\\JDICOM, as default,
    and the given patient folder, e.g.,"PatientLiver" as a default

    :params: str drive: provide the drive
             str root_folder: proive the immediate folder of the drive
             str patient_folder: the patient folder to browse
    """
    CommonActions.left_click_object(MonacoDicomImportObjects.dICOM_Import_Browse_Button)
    CommonActions.left_click_object(MonacoDicomImportObjects.this_PC_TreeItem)
    MonacoDicomImportObjects.drive_TreeItem["text"] = objectmaphelper.Wildcard(f"*({drive})")
    CommonActions.left_click_object(MonacoDicomImportObjects.drive_TreeItem)
    # Alternatively, specifically for C:
    #CommonActions.left_click_object(MonacoDicomImportObjects.windows_C_TreeItem)
    MonacoDicomImportObjects.root_folder_TreeItem["text"] = root_folder

    #the next line skipped as the call next to it can do it first.
    #CommonActions.left_click_object(MonacoDicomImportObjects.root_folder_TreeItem)
    CommonActions.click_item(MonacoDicomImportObjects.root_folder_TreeItem, patient_folder)

    #Alternatively the clicks can also be
    # CommonActions.click_item(MonacoDicomImportObjects.desktop_TreeItem, "This PC")
    # CommonActions.click_item(MonacoDicomImportObjects.desktop_TreeItem, "Windows (C:)")
    # CommonActions.click_item(MonacoDicomImportObjects.desktop_TreeItem,  root_folder)
    # CommonActions.click_item(MonacoDicomImportObjects.desktop_TreeItem,  patient_folder)

    #Click OK button
    CommonActions.click_button(MonacoDicomImportObjects.browse_For_Folder_OK_Button)

@deco.set_separate_app_context(MONACO_APP_NAME)
def browse_by_clicks(path:str):
    """
    Use to browse the given full path of the ptient data folder by clicking each sub-path

    :param: str path: provide the full data path of a patient
    """
    CommonActions.left_click_object(MonacoDicomImportObjects.dICOM_Import_Browse_Button)
    CommonActions.left_click_object(MonacoDicomImportObjects.this_PC_TreeItem)
    treeItems = __get_treeitems(MonacoDicomImportObjects.drive_TreeItem, path)
    for treeItem in treeItems:
        CommonActions.left_click_object(treeItem)
    CommonActions.left_click_object(MonacoDicomImportObjects.browse_For_Folder_OK_Button)

@deco.set_separate_app_context(MONACO_APP_NAME)
def browse_directly(full_path):
    """
    Use to browse the given full path of the ptient data folder directly

    :param: full_path (str): provide the full data path of a patient
    """
    CommonActions.left_click_object(MonacoDicomImportObjects.dICOM_Import_Browse_Button)
    CommonActions.wait_for_object_exists(MonacoDicomImportObjects.browse_For_Folder_Folder_Edit)
    CommonActions.set_text(MonacoDicomImportObjects.browse_For_Folder_Folder_Edit, full_path)
    CommonActions.left_click_object(MonacoDicomImportObjects.browse_For_Folder_OK_Button)

@deco.set_separate_app_context(MONACO_APP_NAME)
def await_browse_done(loops:int = 10) -> bool:
    """
    Wait for the browse action done when the browse button enables again.

    :param: loops (int), count for the loops of waiting with an interval of 1s plus find time.
    :return: a bool, True or False, to indicate if the Browse button is enabled or not after waiting
    """
    browse_button_enable = False
    while (not browse_button_enable) and loops > 0:
        time.sleep(1)
        browse_button = CommonActions.wait_for_object_exists(MonacoDicomImportObjects.dICOM_Import_Browse_Button)
        browse_button_enable = browse_button.enabled if browse_button else False # type: ignore
        loops -=1
    return browse_button_enable


