@deco.set_separate_app_context(MONACO_APP_NAME)
def choose_imageset_from_tree(patient_id:str, study:str, rtimg:str, click: bool):
    """
    Choose an imageset based on the patient id, study, and rtimg parameters.

    :params:patient_id (str): patient id 
            study (str): study id
            rtimg (str): represents the RT image information.
            click (bool): flag to indicate if also to click it
    """
    MonacoDicomImportObjects.root_TreeItem["text"] = patient_id
    root = CommonActions.find_object(MonacoDicomImportObjects.root_TreeItem)
    if root:
        children = CommonActions.get_children(root)
        for child in children:
            if child["text"] == study:
                grand_children =  CommonActions.get_children(child)
                for grand_child in grand_children:
                    if grand_child["text"] == rtimg:
                        if click:
                            CommonActions.left_click_object(grand_child)
                    return

