@deco.set_separate_app_context(MONACO_APP_NAME)
def enable_log(minimized:bool=True) -> int:
    """
    Enable logviewer, and minimize the logviewer window if the minimized parameter is set to True.

    :param: minimized (bool, default=True): specifies whether the logviewer should be minimized.
            If set to True, the log output will be minimized; otherwise, it will be shown in full.

    :returns: int: the hwnd of the logviewer window.
    """
    current_ctx = aut_manager.get_current_app_context()
    CommonActions.left_click_object(MonacoDicomImportObjects.dICOM_Import_Show_Log_Button)
    time.sleep(1)
    ctx_2 = aut_manager.wait_for_application_launch()
    #time.sleep(1)
    logviewer_window = {"class": "Elekta.Interface.LogViewer.MainWindow", "type": "Window"}
    logviewer_window_obj = CommonActions.find_object(logviewer_window,20000)
    logviewer_hwnd = logviewer_window_obj.hwnd if logviewer_window_obj is not None else 0 # type: ignore
    if minimized:
        CommonActions.minimize_window()
    aut_manager.set_app_context(current_ctx.name)
    return logviewer_hwnd

