@deco.set_separate_app_context(MONACO_APP_NAME)
def click_import_button(which_button:int=0, loops:int = 30):
    """
    Click the import button.

    :params: which_button (int), tell which import button( 0:Import, 1:Import and Combine, 2: Import and Replace)
            loops (int), the count of loops with an interval of 1s plus find time.
    """
    button = MonacoDicomImportObjects.dICOM_Import_Import_Button
    if which_button == 1:
        button =  MonacoDicomImportObjects.dICOM_Import_Import_and_Combine_Button
    elif which_button == 2:
        button = MonacoDicomImportObjects.dICOM_Import_Import_and_Replace_Button

    CommonActions.left_click_object(button)
    if which_button == 2:
        if CommonActions.wait_for_object_to_appear(MonacoDicomImportObjects.dICOM_Import_Import_and_Replace_Dialog):
            CommonActions.left_click_object(MonacoDicomImportObjects.dICOM_Import_Import_and_Replace_Yes_Button)
    try:
        obj = CommonActions.wait_for_object_exists(button)
        while obj and obj.enabled and loops > 0: # type: ignore
            print("waiting...")
            time.sleep(1)
            obj = CommonActions.wait_for_object_exists(button)
            loops -= 1
    except Exception:
        pass

